## ⚙️ 2. Расширим структуру клана

Создадим класс `ClanHierarchyBuilder`, который автоматизирует создание иерархии и связывает персонажей:

```ts
import { CharacterEntity } from './character.entity';
import { SocialRelationEntity } from './social/social-relation.entity';
import {
  SocialDuty,
  SocialRight,
  SocialExpectation,
  SocialDutyTag,
  SocialRightTag,
  SocialExpectationTag,
} from './social/social-tags';

interface ClanMemberConfig {
  leader?: CharacterEntity;
  member: CharacterEntity;
  generationLevel: number; // 0 — Матрона, 1 — дочери, 2+ — потомки
}

export class ClanHierarchyBuilder {
  static BASE_RELATIONS = {
    duties: [
      new SocialDuty(SocialDutyTag.GIVE_TRIBUTE, 0.3),
      new SocialDuty(SocialDutyTag.SHOW_RESPECT, 0.8),
      new SocialDuty(SocialDutyTag.CONTRIBUTE_LABOR, 0.6),
    ],
    rights: [
      new SocialRight(SocialRightTag.PROTECTION, 1.0),
      new SocialRight(SocialRightTag.SHARE_LOOT_DOWN, 0.3),
    ],
    expectations: [
      new SocialExpectation(SocialExpectationTag.FAIR_TREATMENT, 0.9),
      new SocialExpectation(SocialExpectationTag.RESPECT, 0.6),
      new SocialExpectation(SocialExpectationTag.MATERIAL_SUPPORT, 0.7),
    ],
  };

  /**
   * Создаёт иерархию между членами клана
   */
  static linkMembers(configs: ClanMemberConfig[], decay = 0.15): void {
    for (const cfg of configs) {
      if (!cfg.leader) continue;

      const levelDecay = Math.max(0, 1 - cfg.generationLevel * decay);

      const relation = new SocialRelationEntity(
        cfg.leader.id,
        cfg.member.id,
        this.BASE_RELATIONS.rights.map(r => new SocialRight(r.tag, r.value * levelDecay)),
        this.BASE_RELATIONS.duties.map(d => new SocialDuty(d.tag, d.value * levelDecay)),
        this.BASE_RELATIONS.expectations.map(e => new SocialExpectation(e.tag, e.value * levelDecay)),
      );

      cfg.leader.addSubordinate(cfg.member, relation);
    }
  }
}
```

