## ⚙️ 2. Расширим `CharacterEntity`

Добавим простую систему инвентарей и экономическую модель:

```ts
import { PrimaryAttributesEntity } from './entities/primary-attributes.entity';
import { SecondaryAttributesEntity } from './entities/secondary-attributes.entity';
import { SocialRelationEntity } from './social/social-relation.entity';
import { SocialDutyTag, SocialRightTag } from './social/social-tags';

type ResourceType = 'food' | 'tools' | 'materials' | 'wealth';

interface Inventory {
  [key: string]: number;
}

export class CharacterEntity {
  id: string;
  name?: string;

  primary: PrimaryAttributesEntity;
  secondary: SecondaryAttributesEntity;

  leaderId: string | null = null;
  subordinates: string[] = [];
  socialRelations: SocialRelationEntity[] = [];

  // 💰 экономика
  privateInventory: Inventory = {}; // личное владение
  sharedInventory: Inventory = {}; // общественные ресурсы

  constructor({
    id = crypto.randomUUID(),
    name,
    primary = new PrimaryAttributesEntity(),
    secondary = new SecondaryAttributesEntity(),
  } = {}) {
    this.id = id;
    this.name = name;
    this.setPrimary(primary, true).setSecondary(secondary, true);
  }

  setPrimary(primary: PrimaryAttributesEntity, copy = false) {
    this.primary = copy ? new PrimaryAttributesEntity(primary) : primary;
    return this;
  }

  setSecondary(secondary: SecondaryAttributesEntity, copy = false) {
    this.secondary = copy ? new SecondaryAttributesEntity(secondary) : secondary;
    return this;
  }

  addSubordinate(subordinate: CharacterEntity, relation: SocialRelationEntity) {
    this.subordinates.push(subordinate.id);
    subordinate.leaderId = this.id;
    this.socialRelations.push(relation);
  }

  getRelationWith(subordinateId: string): SocialRelationEntity | undefined {
    return this.socialRelations.find((r) => r.subordinateId === subordinateId);
  }

  // 📦 инвентарь
  addResource(inventory: 'private' | 'shared', type: ResourceType, amount: number) {
    const inv = inventory === 'private' ? this.privateInventory : this.sharedInventory;
    inv[type] = (inv[type] || 0) + amount;
  }

  removeResource(inventory: 'private' | 'shared', type: ResourceType, amount: number) {
    const inv = inventory === 'private' ? this.privateInventory : this.sharedInventory;
    inv[type] = Math.max(0, (inv[type] || 0) - amount);
  }

  getResource(inventory: 'private' | 'shared', type: ResourceType): number {
    const inv = inventory === 'private' ? this.privateInventory : this.sharedInventory;
    return inv[type] || 0;
  }
}
```

