## ⚙️ 3. Добавим класс `EconomySystem`

Этот класс обрабатывает все вертикальные потоки по тегам.

```ts
import { CharacterEntity } from './character.entity';
import { SocialDutyTag, SocialRightTag } from './social/social-tags';

export class EconomySystem {
  static giveTribute(subordinate: CharacterEntity, leader: CharacterEntity, type: string) {
    const relation = leader.getRelationWith(subordinate.id);
    if (!relation) return;

    const tributeTag = relation.duties.find(d => d.tag === SocialDutyTag.GIVE_TRIBUTE);
    if (!tributeTag) return;

    const ratio = tributeTag.value; // 0–1
    const available = subordinate.getResource('private', type);
    const amount = available * ratio;

    if (amount > 0) {
      subordinate.removeResource('private', type, amount);
      leader.addResource('shared', type, amount);
    }
  }

  static shareLootUp(subordinate: CharacterEntity, leader: CharacterEntity, type: string) {
    const relation = leader.getRelationWith(subordinate.id);
    if (!relation) return;

    const duty = relation.duties.find(d => d.tag === SocialDutyTag.SHARE_LOOT_UP);
    if (!duty) return;

    const ratio = duty.value;
    const available = subordinate.getResource('shared', type);
    const amount = available * ratio;

    if (amount > 0) {
      subordinate.removeResource('shared', type, amount);
      leader.addResource('shared', type, amount);
    }
  }

  static shareLootDown(leader: CharacterEntity, type: string) {
    for (const subId of leader.subordinates) {
      const relation = leader.getRelationWith(subId);
      if (!relation) continue;

      const right = relation.rights.find(r => r.tag === SocialRightTag.SHARE_LOOT_DOWN);
      if (!right) continue;

      const ratio = right.value;
      const available = leader.getResource('shared', type);
      const amount = available * ratio / leader.subordinates.length;

      if (amount > 0) {
        const subordinate = allCharacters.find(c => c.id === subId); // упрощённо
        if (subordinate) {
          leader.removeResource('shared', type, amount);
          subordinate.addResource('shared', type, amount);
        }
      }
    }
  }
}
```

