## ⚙️ 2. Расширим `SocialRelationEntity`

Добавим в отношения динамические показатели восприятия:

```ts
export class SocialRelationEntity {
  leaderId: string;
  subordinateId: string;

  rights: SocialRight[] = [];
  duties: SocialDuty[] = [];
  expectations: SocialExpectation[] = [];

  // 💬 психологические параметры
  trust: number = 0.7;   // доверие
  respect: number = 0.7; // уважение
  fear: number = 0.3;    // страх

  get loyalty(): number {
    // взвешенное среднее: можно калибровать
    return (this.trust * 0.4 + this.respect * 0.4 + this.fear * 0.2);
  }

  constructor(
    leaderId: string,
    subordinateId: string,
    rights: SocialRight[] = [],
    duties: SocialDuty[] = [],
    expectations: SocialExpectation[] = []
  ) {
    this.leaderId = leaderId;
    this.subordinateId = subordinateId;
    this.rights = rights;
    this.duties = duties;
    this.expectations = expectations;
  }
}
```

